head.b:skin:
/* 
-----------------------------------------------
Job Template Style
Name:        tripuragovtjobsupdates
Version:     Customised
Author:      Uttam Das
Author Url:  #
----------------------------------------------- */

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="$(main.color)" value="#17365D"/>
<Variable name="followByEmail" description="Follow By Email Text" type="string" default="Get all latest content delivered straight to your inbox." value="Get all latest content delivered straight to your inbox."/>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background Color" type="color" default="#f3f3f3"  value="#f3f3f3"/>
  <Variable name="body.background" description="Background" type="background" color="$(body.background.color)" default="$(color) url() repeat scroll top left" value="$(color) url() repeat scroll top left"/>
  <Variable name="body.text.color" description="Text Color" type="color" default="#656565"  value="#656565"/>
  <Variable name="body.link.color" description="Link Color" type="color" default="$(main.color)"  value="#17365D"/>
</Group>

<Group description="Theme Colors" selector="body">
 <Variable name="main.color" description="Theme Color" type="color" default="#17365D" value="#17365D"/>
  <Variable name="main.dark.color" description="Dark Color" type="color" default="#14243A" value="#14243A"/>
  <Variable name="header.bg" description="Header Background" type="color" default="#17365D" value="#17365D"/>
  <Variable name="title.color" description="Title Color" type="color" default="#14243A" value="#14243A"/>
  <Variable name="title.hover" description="Title Color on Hover" type="color" default="$(main.color)" value="#17365D"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#ffffff" value="#ffffff"/>
</Group>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="14px Montserrat, sans-serif"  value="14px Montserrat, sans-serif"/>
<Variable name="posts.background.color" description="Post background color" hideEditor="true" type="color" default="#ffffff"  value="#ffffff"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="14px Montserrat, sans-serif"  value="14px Montserrat, sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="#14243A"  value="#14243A"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="#656565"  value="#656565"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#17365D"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#17365D"/>
*/

/*-- Reset CSS --*/
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}form,textarea,input,button{-webkit-appearance:none;-moz-appearance:none;appearance:none;border-radius:0}dl,ul{list-style-position:inside;font-weight:400;list-style:none}ul li{list-style:none}caption,th{text-align:center}img{border:none;position:relative}a,a:visited{text-decoration:none}.clearfix{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:$(body.link.color)}a img{border:0}abbr{text-decoration:none}.CSS_LIGHTBOX{z-index:999999!important}.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}.center{display:table;margin:0 auto;position:relative}.widget > h2,.widget > h3{display:none}

/*-- Body Content CSS --*/
body{background:$(body.background);background-color:$(body.background.color);font-family:'Montserrat',sans-serif;font-size:14px;font-weight:400;color:$(body.text.color);word-wrap:break-word;margin:0;padding:0}
#outer-wrapper{max-width:1020px;margin:0 auto;background-color:#fff;box-shadow:0 0 5px rgba(0,0,0,.1)}
.row{width:960px}
#content-wrapper{margin:30px auto 0;overflow:hidden}
#content-wrapper > .container{margin:0 -15px}
#main-wrapper{float:left;overflow:hidden;width:66.66666667%;box-sizing:border-box;word-wrap:break-word;padding:0 15px;margin:0}
#sidebar-wrapper{float:right;overflow:hidden;width:33.33333333%;box-sizing:border-box;word-wrap:break-word;padding:0 15px}
.post-image-link,.about-author .avatar-container,.comments .avatar-image-container{background-color:rgba(155,155,155,0.1);color:transparent!important;transition:background .17s ease}
.post-thumb{display:block;position:relative;width:100%;height:100%;object-fit:cover;z-index:1}
img.post-thumb[src*="nth.png"]{display:none!important}
a.post-image-link:has(> img.post-thumb[src*="nth.png"]){display:none!important}
.post-title a{display:block}
.social a:before{display:inline-block;font-family:FontAwesome;font-style:normal;font-weight:400}
.social .facebook a:before{content:"\f09a"}
.social .telegram a:before{content:"\f2c6"}
.social .twitter a:before{content:"\f099"}
.social .gplus a:before{content:"\f0d5"}
.social .rss a:before{content:"\f09e"}
.social .youtube a:before{content:"\f16a"}
.social .skype a:before{content:"\f17e"}
.social .stumbleupon a:before{content:"\f1a4"}
.social .tumblr a:before{content:"\f173"}
.social .vk a:before{content:"\f189"}
.social .stack-overflow a:before{content:"\f16c"}
.social .github a:before{content:"\f09b"}
.social .linkedin a:before{content:"\f0e1"}
.social .dribbble a:before{content:"\f17d"}
.social .soundcloud a:before{content:"\f1be"}
.social .behance a:before{content:"\f1b4"}
.social .digg a:before{content:"\f1a6"}
.social .instagram a:before{content:"\f16d"}
.social .pinterest a:before{content:"\f0d2"}
.social .twitch a:before{content:"\f1e8"}
.social .delicious a:before{content:"\f1a5"}
.social .codepen a:before{content:"\f1cb"}
.social .reddit a:before{content:"\f1a1"}
.social .whatsapp a:before{content:"\f232"}
.social .snapchat a:before{content:"\f2ac"}
.social .email a:before{content:"\f0e0"}
.social .external-link a:before{content:"\f35d"}
.social-color .facebook a{background-color:#3b5999}
.social-color .twitter a{background-color:#00acee}
.social-color .gplus a{background-color:#db4a39}
.social-color .youtube a{background-color:#db4a39}
.social-color .instagram a{background:linear-gradient(15deg,#ffb13d,#dd277b,#4d5ed4)}
.social-color .pinterest a{background-color:#ca2127}
.social-color .dribbble a{background-color:#ea4c89}
.social-color .linkedin a{background-color:#0077b5}
.social-color .tumblr a{background-color:#365069}
.social-color .twitch a{background-color:#6441a5}
.social-color .rss a{background-color:#ffc200}
.social-color .skype a{background-color:#00aff0}
.social-color .stumbleupon a{background-color:#eb4823}
.social-color .vk a{background-color:#4a76a8}
.social-color .stack-overflow a{background-color:#f48024}
.social-color .github a{background-color:#24292e}
.social-color .soundcloud a{background:linear-gradient(#ff7400,#ff3400)}
.social-color .behance a{background-color:#191919}
.social-color .digg a{background-color:#1b1a19}
.social-color .delicious a{background-color:#0076e8}
.social-color .codepen a{background-color:#000}
.social-color .reddit a{background-color:#ff4500}
.social-color .whatsapp a{background-color:#3fbb50}
.social-color .snapchat a{background-color:#ffe700}
.social-color .email a{background-color:#888}
.social-color .external-link a{background-color:$(main.dark.color)}
.social-text .facebook a:after{content:"Facebook"}
.social-text .twitter a:after{content:"Twitter"}
.social-text .gplus a:after{content:"Google Plus"}
#header-wrap{position:relative;margin:0}
.header-header{background-color:$(header.bg);width:100%;height:90px;position:relative;overflow:hidden;padding:25px 0}
.header-header .container{position:relative;margin:0 auto;padding:0}
.header-logo{position:relative;float:left;width:auto;max-width:200px;max-height:60px;margin:0;padding:15px 0}
.header-logo .header-image-wrapper{display:block}
.header-logo img{max-width:100%;max-height:60px;margin:0}
.header-logo h1{color:#fff;font-size:27px;line-height:60px;text-transform:uppercase;margin:0}
.header-logo p{font-size:12px;margin:5px 0 0}
.header-ads{position:relative;float:right}
.header-ads .widget > .widget-title{display:none}
.header-ads .widget{max-width:100%}
.header-ads .widget .widget-content{width:728px;max-width:100%;max-height:90px;line-height:1}
.header-menu{position:relative;width:100%;height:46px;background-color:$(main.dark.color);z-index:1010;font-size:13px;margin:0}
.header-menu .container{position:relative;margin:0 auto;padding:0}
#main-menu .widget,#main-menu .widget > .widget-title{display:none}
#main-menu .show-menu{display:block}
#main-menu{position:relative;height:46px;z-index:15}
#main-menu ul > li{float:left;position:relative;margin:0;padding:0;transition:background .17s}
#main-menu ul > li > a{position:relative;color:#fff;font-size:15px;font-weight:400;line-height:46px;display:inline-block;margin:0;padding:0 15px;transition:color .17s ease}
#main-menu #main-menu-nav > li:first-child > a{padding-left:0}
#main-menu ul > li:hover > a{text-decoration:underline}
#main-menu ul > li > ul{position:absolute;float:left;left:0;top:46px;width:180px;background-color:$(main.dark.color);z-index:99999;margin-top:0;padding:0;visibility:hidden;opacity:0}
#main-menu ul > li > ul > li > ul{position:absolute;float:left;top:0;left:100%;margin:0}
#main-menu ul > li > ul > li{display:block;float:none;position:relative}
#main-menu ul > li > ul > li a{display:block;height:36px;font-size:13px;color:#fff;line-height:36px;box-sizing:border-box;margin:0;padding:0 15px;border:0;transition:all .17s ease}
#main-menu ul > li.has-sub > a:after{content:'\f107';float:right;font-family:FontAwesome;font-size:12px;font-weight:400;margin:0 0 0 5px}
#main-menu ul > li > ul > li.has-sub > a:after{content:'\f105';float:right;margin:0}
#main-menu ul > li:hover > ul,#main-menu ul > li > ul > li:hover > ul{visibility:visible;opacity:1}
#main-menu ul ul{transition:all .25s ease}
.show-search,.hide-search{position:absolute;right:0;top:0;display:block;width:30px;height:46px;background-color:$(main.dark.color);line-height:46px;z-index:20;color:#fff;font-size:15px;text-align:right;cursor:pointer;padding:0;transition:background .17s ease}
.show-search:before{content:"\f002";font-family:FontAwesome;font-weight:400}
.hide-search:before{content:"\f00d";font-family:FontAwesome;font-weight:400}
#nav-search{display:none;position:absolute;left:0;top:0;width:100%;height:46px;z-index:99;background-color:$(main.dark.color);box-sizing:border-box;padding:0}
#nav-search .search-form{width:100%;height:46px;background-color:rgba(0,0,0,0);line-height:46px;overflow:hidden;padding:0}
#nav-search .search-input{width:100%;height:46px;font-family:inherit;color:#fff;margin:0;padding:0 46px 0 0;background-color:rgba(0,0,0,0);font-size:13px;font-weight:400;outline:none;box-sizing:border-box;border:0}
.mobile-nav{display:none;position:absolute;width:100%;height:46px;top:46px;left:0}
.overlay{display:none!important;pointer-events:none!important;position:fixed;top:0;left:0;right:0;bottom:0;z-index:990;background:rgba(0,0,0,0.5)}.nav-active .overlay{display:block!important;pointer-events:auto!important}
.slide-menu-toggle{display:none;position:absolute;line-height:46px;height:46px;width:46px;top:0;left:0;font-family:FontAwesome;color:#fff;font-size:18px;font-weight:400;text-align:center;cursor:pointer;z-index:4;padding:0}
.slide-menu-toggle:before{content:"\f0c9"}
.nav-active .slide-menu-toggle:before{content:"\f00d"}
.show-mobile-search:before{content:"\f002"}
.hide-mobile-search:before{content:"\f00d"}
.mobile-menu{position:relative;float:left;width:100%;background-color:$(main.dark.color);box-sizing:border-box;padding:20px;border-top:1px solid rgba(255,255,255,0.08);visibility:hidden;opacity:0;transform-origin:0 0;transform:scaleY(0);transition:all .17s ease}
.nav-active .mobile-menu{visibility:visible;opacity:1;transform:scaleY(1)}
.mobile-menu > ul{margin:0}
.mobile-menu .m-sub{display:none;padding:0}
.mobile-menu ul li{position:relative;display:block;overflow:hidden;float:left;width:100%;font-size:14px;line-height:38px;margin:0;padding:0;border-top:1px solid rgba(255,255,255,0.01)}
.mobile-menu > ul > li{font-weight:400}
.mobile-menu > ul li ul{overflow:hidden}
.mobile-menu > ul > li:first-child{border-top:0}
.mobile-menu ul li a{color:#fff;padding:0;display:block;transition:all .17s ease}
.mobile-menu #main-menu-nav > li > a{font-weight:400;font-size:14px}
.mobile-menu ul li.has-sub .submenu-toggle{position:absolute;top:0;right:0;color:#fff;cursor:pointer}
.mobile-menu ul li.has-sub .submenu-toggle:after{content:'\f105';font-family:FontAwesome;font-weight:400;float:right;width:34px;font-size:16px;text-align:center;transition:all .17s ease}
.mobile-menu ul li.has-sub.show > .submenu-toggle:after{transform:rotate(90deg)}
.mobile-menu > ul > li > ul > li a{font-size:13px}
.mobile-menu > ul > li > ul > li > a{color:#fff;opacity:.7;padding:0 0 0 15px}
.mobile-menu > ul > li > ul > li > ul > li > a{color:#fff;opacity:.7;padding:0 0 0 30px}
.mobile-menu ul > li > .submenu-toggle:hover{color:$(main.color)}
.post-meta{display:block;overflow:hidden;color:#555555;font-size:12px;font-weight:400;padding:0 1px}
.post-meta .post-author,.post-meta .post-date{float:left;margin:0 10px 0 0}
.post-meta .post-date{text-transform:capitalize}
.post-meta a,.post-author,.post-date{color:#555;transition:color .17s}
.post-meta a:hover{color:$(title.hover)}
.post-author:before,.post-date:before{font-family:FontAwesome;font-weight:400;margin:0 3px 0 0}
.post-author:before{content:'\f2c0'}
.post-date:before{content:'\f017'}
#hot-wrapper{margin:0 auto}
#hot-section .widget,#hot-section .widget > .widget-title{display:none}
#hot-section .show-hot{display:block!important}
#hot-section .show-hot .widget-content{position:relative;overflow:hidden;min-height:140px;margin:30px 0 0}
.hot-loader{position:relative;min-height:140px;overflow:hidden;display:block}
.hot-loader:after{content:'';position:absolute;top:50%;left:50%;width:26px;height:26px;margin:-15px 0 0 -15px;border:2px solid #ebebeb;border-left-color:$(main.color);border-top-color:$(main.color);border-radius:100%;animation:spinner .8s infinite linear;transform-origin:center}
@-webkit-keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
@keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
ul.hot-posts{position:relative;overflow:hidden;display:flex;flex-wrap:wrap;min-height:140px;margin:0 -5px}
.hot-posts .hot-item{position:relative;float:left;display:flex;width:calc(100% / 3);overflow:hidden;box-sizing:border-box;padding:0 5px;margin:10px 0 0}
.hot-posts .item-0,.hot-posts .item-1,.hot-posts .item-2{margin:0}
.hot-item-inner{position:relative;float:left;width:100%;background-color:$(main.dark.color);overflow:hidden;box-sizing:border-box;padding:10px}
#HTML2 .hot-posts-color .hot-item-inner{background-color:#f5f8fc!important;border:1px solid #dfe7f0;border-left:3px solid #d5a548;border-radius:8px}
.hot-posts .post-image-link{float:left;width:45px;height:45px;background-color:rgba(255,255,255,0.5);position:relative;overflow:hidden;display:block;box-sizing:border-box;padding:2px;margin:0 10px 0 0;transition:background .17s ease}
.hot-posts .hot-item-inner:hover .post-image-link{background-color:$(main.color)}
.hot-posts-color .hot-item-inner:hover .post-image-link{background-color:#fff}
.hot-posts .post-info{overflow:hidden}
.hot-posts .post-title{font-size:13px;font-weight:400;display:block;line-height:1.5em;margin:0}
.hot-posts .post-title a{color:#fff}
.hot-posts .hot-item-inner:hover .post-title .title-text{text-decoration:underline}
.post-title .title-text{margin:0 10px 0 0;transition:color .17s ease}
.post-title .post-date{font-size:11px;color:#555555}
.hot-posts .post-title .post-date{color:#f2f2f2}
#HTML2 .hot-posts-color .post-title a{color:#17365d!important}
#HTML2 .hot-posts-color .post-title .post-date{color:#64748b!important}
.show-hot .no-posts{position:absolute;top:calc(50% - 50px);left:0;width:100%;text-align:center}
.queryMessage{overflow:hidden;background-color:$(main.dark.color);color:#fff;font-size:13px;font-weight:400;padding:8px 10px;margin:0}
.queryMessage .query-info{margin:0 5px}
.queryMessage .search-query,.queryMessage .search-label{font-weight:700;text-transform:uppercase}
.queryMessage .search-query:before,.queryMessage .search-label:before{content:"\201c"}
.queryMessage .search-query:after,.queryMessage .search-label:after{content:"\201d"}
.queryMessage a.show-more{float:right;color:#fff}
.queryMessage a.show-more:hover{text-decoration:underline}
.queryEmpty{font-size:13px;font-weight:400;padding:10px 0;margin:25px 0;text-align:center}
.title-wrap,.featured-posts .widget-title{position:relative;float:left;width:100%;height:30px;background-color:$(main.dark.color);display:block;margin:0}
.title-wrap > h3,.featured-posts .widget-title > h3{float:left;height:30px;font-size:14px;color:#fff;font-weight:400;line-height:32px;padding:0 15px;margin:0}
a.view-all{float:right;font-size:11px;color:#fff;line-height:30px;padding:0 15px}
a.view-all:hover{text-decoration:underline}
a.view-all:after{content:"\f105";float:right;font-weight:400;font-family:FontAwesome;margin:0 0 0 3px}
.featured-posts > .widget{display:none;position:relative;float:left;width:100%;margin:0 0 30px}
.featured-posts > .show-widget{display:block}
.featured-posts .widget-content{float:left;width:100%;box-sizing:border-box;padding:15px;border:2px solid $(main.dark.color)}
.featured-posts > .col-width{width:calc(50% - 15px)}
.featured-posts > .col-right{float:right}
.feat-x1 li{position:relative;float:left;width:100%;overflow:hidden;padding:10px 0 0;margin:10px 0 0;border-top:1px dashed #ebebeb}
.feat-x1 li.item-0{padding:0;margin:0;border:0}
.feat-x1 .post-image-link{position:relative;float:left;width:45px;height:45px;display:block;overflow:hidden;box-sizing:border-box;padding:2px;margin:0 10px 0 0}
.feat-x1 .feat-item:hover .post-image-link{background-color:$(main.color)}
.feat-x1 .post-title{overflow:hidden;font-size:13px;font-weight:400;line-height:1.5em;margin:0 0 5px}
.feat-x1 .item-small .post-info{overflow:hidden}
.feat-x1 .post-title a{color:$(title.color)}
.feat-x1 .feat-item:hover .post-title .title-text{color:$(title.hover);text-decoration:underline}
.index-post-wrap{float:left;width:100%;box-sizing:border-box;padding:15px;margin:0 0 30px;border:2px solid #111}
.no-index-posts{padding:0;border:0}
.blog-post{display:block;overflow:hidden;word-wrap:break-word}
.index-post{padding:10px 0 0;margin:10px 0 0;border-top:1px dashed #ebebeb}
.blog-posts .index-post:first-child{padding:0;margin:0;border:0}
.index-post .post-image-link{float:left;width:45px;height:45px;position:relative;display:block;z-index:1;overflow:hidden;box-sizing:border-box;padding:2px;margin:0 10px 0 0}
.index-post:hover .post-image-link{background-color:$(main.color)}
.index-post .post-info{overflow:hidden}
.index-post .post-info .post-title{font-size:13px;font-weight:400;line-height:1.5em;text-decoration:none;margin:0}
.index-post .post-info .post-title a{display:block;color:$(title.color)}
.index-post:hover .post-info .post-title .title-text{color:$(title.hover);text-decoration:underline}
.widget iframe,.widget img{max-width:100%}
.date-header{display:block;overflow:hidden;font-weight:400;margin:0!important;padding:0}
.post-timestamp{margin-left:0}
#breadcrumb{font-size:12px;font-weight:400;color:#555555;margin:0 0 10px}
#breadcrumb a{color:#555555;transition:color .17s}
#breadcrumb a:hover{color:$(title.hover)}
#breadcrumb a,#breadcrumb em{display:inline-block}
#breadcrumb .delimiter:after{content:'\f105';font-family:FontAwesome;font-style:normal;margin:0 3px}
.item-post h1.post-title{color:$(title.color);font-size:27px;line-height:1.5em;font-weight:700;position:relative;display:block;margin:15px 0;padding:0}
.static_page .item-post h1.post-title{padding:0 0 10px;margin:0;border-bottom:1px solid #ebebeb}
.item-post .post-body{width:100%;line-height:1.5em;overflow:hidden;padding:20px 0 0}
.static_page .item-post .post-body{padding:20px 0}
.item-post .post-outer{padding:0}
.item-post .post-body img{max-width:100%}
.item-post .post-meta{padding:0 1px 10px;border-bottom:1px solid #ebebeb}
.main .widget{margin:0}
.main .Blog{border-bottom-width:0}
.post-footer{position:relative;float:left;width:100%;margin:20px 0 0}
.inline-ad{position:relative;display:block;max-height:60px;margin:0 0 30px}
.inline-ad > ins{display:block!important;margin:0 auto!important}
.item .inline-ad{float:left;width:100%;margin:20px 0 0}
.item-post-wrap > .inline-ad{margin:0 0 20px}
.post-labels{overflow:hidden;height:auto;position:relative;padding:0;margin:0 0 25px}
.post-labels span,.post-labels a{float:left;color:#555555;font-size:12px;font-weight:400;margin:0 12px 0 0;transition:all .17s ease}
.post-labels span{color:$(title.color)}
.post-labels a:hover{color:$(main.color);text-decoration:underline}
.post-share{position:relative;overflow:hidden;line-height:0;margin:0 0 30px}
ul.share-links{position:relative}
.share-links li{width:32px;float:left;box-sizing:border-box;margin:0 5px 0 0}
.share-links li.facebook,.share-links li.twitter,.share-links li.gplus{width:20%}
.share-links li a{float:left;display:inline-block;cursor:pointer;width:100%;height:32px;line-height:32px;color:#fff;font-weight:400;font-size:13px;text-align:center;box-sizing:border-box;opacity:1;margin:0;padding:0;transition:all .17s ease}
.share-links li.whatsapp-mobile{display:none}
.is-mobile li.whatsapp-desktop{display:none}
.is-mobile li.whatsapp-mobile{display:inline-block}
.share-links li a:before{float:left;display:block;width:32px;background-color:rgba(255,255,255,0.07);font-size:15px;text-align:center;line-height:32px}
.share-links li a:hover{opacity:.8}
ul.post-nav{position:relative;overflow:hidden;display:block;margin:0 0 30px}
.post-nav li{display:inline-block;width:50%}
.post-nav .post-prev{float:left;text-align:left;box-sizing:border-box;padding:0 10px}
.post-nav .post-next{float:right;text-align:right;box-sizing:border-box;padding:0 10px}
.post-nav li a{color:$(title.color);line-height:1.4em;display:block;overflow:hidden;transition:color .17s}
.post-nav li:hover a{color:$(title.hover)}
.post-nav li:hover a p{text-decoration:underline}
.post-nav li span{display:block;font-size:11px;color:#555555;font-weight:700;text-transform:uppercase;padding:0 0 2px}
.post-nav .post-prev span:before{content:"\f053";float:left;font-family:FontAwesome;font-size:9px;font-weight:400;text-transform:none;margin:0 2px 0 0}
.post-nav .post-next span:after{content:"\f054";float:right;font-family:FontAwesome;font-size:9px;font-weight:400;text-transform:none;margin:0 0 0 2px}
.post-nav p{font-size:12px;font-weight:400;line-height:1.4em;margin:0}
.post-nav .post-nav-active p{color:#555555}
.about-author{position:relative;display:block;overflow:hidden;padding:20px;margin:0 0 30px;border:1px solid #ebebeb}
.about-author .avatar-container{position:relative;float:left;width:80px;height:80px;overflow:hidden;margin:0 15px 0 0}
.about-author .author-avatar{float:left;width:100%;height:100%}
.author-name{overflow:hidden;display:inline-block;font-size:16px;font-weight:700;margin:7px 0 3px}
.author-name span{color:$(title.color)}
.author-name a{color:$(title.color);transition:color .17s}
.author-name a:hover{color:$(main.color);text-decoration:underline}
.author-description{display:block;overflow:hidden;font-size:13px;font-weight:400;line-height:1.5em}
.author-description a:hover{text-decoration:underline}
#related-wrap{display:none;overflow:hidden;margin:0 0 30px}
.show-related{display:block!important}
#related-wrap .related-tag{display:none}
.related-ready{float:left;width:100%;box-sizing:border-box;padding:15px;border:2px solid $(main.dark.color)}
#blog-pager{overflow:hidden;clear:both;margin:0 0 30px}
.blog-pager a,.blog-pager span{float:left;display:block;min-width:28px;height:28px;background-color:$(main.dark.color);color:#fff;font-size:13px;font-weight:400;line-height:28px;text-align:center;box-sizing:border-box;margin:0 5px 0 0;transition:all .17s ease}
.blog-pager .blog-pager-newer-link,.blog-pager .blog-pager-older-link{padding:0 15px}
.blog-pager .blog-pager-newer-link{float:left}
.blog-pager .blog-pager-older-link{float:right}
.blog-pager span.page-dots{min-width:20px;background-color:#fff;font-size:16px;color:$(title.color);line-height:30px;font-weight:400;letter-spacing:-1px;border:0}
.blog-pager .page-of{display:none;width:auto;float:right;border-color:rgba(0,0,0,0);margin:0}
.blog-pager .page-active,.blog-pager a:hover{background-color:$(main.color);color:#fff}
.blog-pager .page-prev:before,.blog-pager .page-next:before{font-family:FontAwesome;font-size:16px;font-weight:400}
.blog-pager .page-prev:before{content:'\f104'}
.blog-pager .page-next:before{content:'\f105'}
.blog-pager .blog-pager-newer-link:after{content:'\f104';float:left;font-family:FontAwesome;font-weight:400;margin:0 3px 0 0}
.blog-pager .blog-pager-older-link:after{content:'\f105';float:right;font-family:FontAwesome;font-weight:400;margin:0 0 0 3px}
.archive #blog-pager{display:none}
.blog-post-comments{display:none;margin:0 0 30px}
.blog-post-comments .comments-title{margin:0 0 20px}
.comments-system-disqus .comments-title,.comments-system-facebook .comments-title{margin:0}
#comments{margin:0}
#gpluscomments{float:left!important;width:100%!important;margin:0 0 25px!important}
#gpluscomments iframe{float:left!important;width:100%}
.comments{display:block;clear:both;margin:0;color:$(title.color)}
.comments > h3{font-size:13px;font-weight:400;font-style:italic;padding-top:1px}
.comments .comments-content .comment{list-style:none;margin:0;padding:0 0 8px}
.comments .comments-content .comment:first-child{padding-top:0}
.facebook-tab,.fb_iframe_widget_fluid span,.fb_iframe_widget iframe{width:100%!important}
.comments .item-control{position:static}
.comments .avatar-image-container{float:left;overflow:hidden;position:absolute}
.comments .avatar-image-container,.comments .avatar-image-container img{height:45px;max-height:45px;width:45px;max-width:45px;border-radius:0}
.comments .comment-block{overflow:hidden;padding:0 0 10px}
.comments .comment-block,.comments .comments-content .comment-replies{margin:0 0 0 60px}
.comments .comments-content .inline-thread{padding:0}
.comments .comment-actions{float:left;width:100%;position:relative;margin:0}
.comments .comments-content .comment-header{font-size:12px;display:block;overflow:hidden;clear:both;margin:0 0 3px;padding:0 0 5px;border-bottom:1px dashed #ebebeb}
.comments .comments-content .comment-header a{color:$(title.color);transition:color .17s}
.comments .comments-content .comment-header a:hover{color:$(title.hover)}
.comments .comments-content .user{font-style:normal;font-weight:700;text-transform:uppercase;display:block}
.comments .comments-content .icon.blog-author{display:none}
.comments .comments-content .comment-content{float:left;font-size:13px;color:#5E5E5E;font-weight:400;text-align:left;line-height:1.4em;margin:5px 0 9px}
.comments .comment .comment-actions a{margin-right:5px;padding:2px 5px;color:$(title.color);font-weight:400;border:1px solid #f5f5f5;font-size:10px;transition:all .17s ease}
.comments .comment .comment-actions a:hover{color:#fff;background-color:$(main.color);border-color:$(main.color);text-decoration:none}
.comments .comments-content .datetime{float:left;font-size:11px;font-weight:400;color:#555555;position:relative;padding:0 1px;margin:4px 0 0;display:block}
.comments .comments-content .datetime a,.comments .comments-content .datetime a:hover{color:#555555}
.comments .comments-content .datetime:before{content:'\f017';font-family:FontAwesome;font-size:11px;font-weight:400;font-style:normal;margin:0 3px 0 0}
.comments .thread-toggle{margin-bottom:4px}
.comments .thread-toggle .thread-arrow{height:7px;margin:0 3px 2px 0}
.comments .thread-count a,.comments .continue a{transition:opacity .17s}
.comments .thread-count a:hover,.comments .continue a:hover{opacity:.8}
.comments .thread-expanded{padding:5px 0 0}
.comments .thread-chrome.thread-collapsed{display:none}
.thread-arrow:before{content:'';font-family:FontAwesome;color:$(title.color);font-weight:400;margin:0 2px 0 0}
.comments .thread-expanded .thread-arrow:before{content:'\f0d7'}
.comments .thread-collapsed .thread-arrow:before{content:'\f0da'}
.comments .comments-content .comment-thread{margin:0}
.comments .comments-content .comment-thread > ol{padding:0}
.comments .continue a{padding:0 0 0 60px;font-weight:400}
.comments .comments-content .loadmore.loaded{margin:0;padding:0}
.comments .comment-replybox-thread{margin:0}
.comments .comments-content .loadmore,.comments .comments-content .loadmore.loaded{display:none}
.post-body h1,.post-body h2,.post-body h3,.post-body h4,.post-body h5,.post-body h6{color:$(title.color);margin:0 0 15px}
.post-body h1,.post-body h2{font-size:24px}
.post-body h3{font-size:21px}
.post-body h4{font-size:18px}
.post-body h5{font-size:16px}
.post-body h6{font-size:13px}
blockquote{font-style:italic;padding:10px;margin:0;border-left:4px solid $(main.color)}
blockquote:before,blockquote:after{display:inline-block;font-family:FontAwesome;font-style:normal;font-weight:400;color:#555555;line-height:1}
blockquote:before{content:'\f10d';margin:0 10px 0 0}
blockquote:after{content:'\f10e';margin:0 0 0 10px}
.widget .post-body ul,.widget .post-body ol{line-height:1.5;font-weight:400}
.widget .post-body li{margin:5px 0;padding:0;line-height:1.5}
.post-body ul{padding:0 0 0 20px}
.post-body ul li:before{content:"\f105";font-family:FontAwesome;font-size:13px;font-weight:400;margin:0 5px 0 0}
.post-body u{text-decoration:underline}
.post-body a{transition:color .17s ease}
.post-body strike{text-decoration:line-through}
.contact-form{overflow:hidden}
.contact-form .widget-title{display:none}
.contact-form .contact-form-name{width:calc(50% - 5px)}
.contact-form .contact-form-email{width:calc(50% - 5px);float:right}
.sidebar .widget{position:relative;overflow:hidden;background-color:#fff;box-sizing:border-box;padding:0;margin:0 0 30px}
.sidebar .widget-title{position:relative;float:left;width:100%;height:30px;background-color:$(main.dark.color);display:block;margin:0}
.sidebar .widget-title > h3{float:left;height:30px;font-size:14px;color:#fff;line-height:32px;font-weight:400;padding:0 15px;margin:0}
.sidebar .widget-content{float:left;width:100%;box-sizing:border-box;padding:15px;margin:0;border:2px solid $(main.dark.color)}
ul.social-counter{margin:0 -5px}
.social-counter li{float:left;width:calc(100% / 6);box-sizing:border-box;padding:0 5px;margin:10px 0 0}
.social-counter li:nth-child(1),.social-counter li:nth-child(2),.social-counter li:nth-child(3),.social-counter li:nth-child(4),.social-counter li:nth-child(5),.social-counter li:nth-child(6){margin-top:0}
.social-counter li:nth-child(even){float:right}
#social-widget .social-counter{display:flex;flex-wrap:wrap;gap:8px;margin:0}
#social-widget .social-counter li{float:none;flex:0 0 37px;width:37px;padding:0;margin:0}
.social-counter li a{display:block;height:34px;font-size:14px;color:#fff;line-height:34px;text-align:center;transition:opacity .17s}
.social-counter li a:hover{opacity:.8}
.list-label li{position:relative;display:block;padding:8px 0;border-top:1px dashed #ebebeb}
.list-label li:first-child{padding:0 0 8px;border-top:0}
.list-label li:last-child{padding-bottom:0;border-bottom:0}
.list-label li a{display:block;color:$(title.color);font-size:13px;font-weight:400;text-transform:capitalize;transition:color .17s}
.list-label li a:before{content:"\f105";float:left;font-size:12px;color:$(title.color);font-weight:400;font-family:FontAwesome;margin:1px 3px 0 0;transition:color .17s}
.list-label li a:hover{color:$(title.hover);text-decoration:underline}
.list-label .label-count{position:relative;float:right;width:16px;height:16px;background-color:$(main.color);color:#fff;font-size:11px;font-weight:400;text-align:center;line-height:16px}
.cloud-label li{position:relative;float:left;margin:0 5px 5px 0}
.cloud-label li a{display:block;height:26px;background-color:$(main.color);color:#fff;font-size:12px;line-height:26px;font-weight:400;padding:0 10px;transition:all .17s ease}
.cloud-label li a:hover{background-color:$(main.dark.color)}
#sidebar2 #Label2.widget.Label .widget-content.cloud-label li a.label-name{background-color:#edf2f7!important;color:#17365d!important}
#sidebar2 #Label2.widget.Label .widget-content.cloud-label li a.label-name:hover{background-color:#dbe5f0!important;color:#102744!important}
.cloud-label .label-count{display:none}
.sidebar .FollowByEmail > .widget-title > h3{margin:0}
.FollowByEmail .widget-content{position:relative;overflow:hidden;font-weight:400;text-align:center;box-sizing:border-box;padding:20px;border:2px solid $(main.dark.color)}
.FollowByEmail .widget-content > h3{font-size:18px;color:$(title.color);font-weight:700;margin:0 0 13px}
.FollowByEmail .before-text{font-size:13px;color:#888;line-height:1.4em;margin:0 0 15px;display:block;padding:0 15px;overflow:hidden}
.FollowByEmail .follow-by-email-inner{position:relative}
.FollowByEmail .follow-by-email-inner .follow-by-email-address{width:100%;height:34px;color:#888;font-size:11px;font-family:inherit;text-align:center;padding:0 10px;margin:0 0 10px;box-sizing:border-box;border:1px solid #ebebeb;transition:ease .17s}
.FollowByEmail .follow-by-email-inner .follow-by-email-address:focus{border-color:rgba(0,0,0,0.1)}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit{width:100%;height:34px;font-family:inherit;font-size:11px;color:#fff;background-color:$(main.color);text-transform:uppercase;text-align:center;font-weight:700;cursor:pointer;margin:0;border:0;transition:background .17s}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover{background-color:$(main.dark.color)}
#ArchiveList ul.flat li{color:$(title.color);font-size:13px;font-weight:400;padding:8px 0;border-bottom:1px dashed #ebebeb}
#ArchiveList ul.flat li:first-child{padding-top:0}
#ArchiveList ul.flat li:last-child{padding-bottom:0;border-bottom:0}
#ArchiveList .flat li > a{display:block;color:$(title.color);transition:color .17s}
#ArchiveList .flat li > a:hover{color:$(title.hover);text-decoration:underline}
#ArchiveList .flat li > a:before{content:"\f105";float:left;font-size:12px;color:$(title.color);font-weight:400;font-family:FontAwesome;margin:1px 3px 0 0;display:inline-block;transition:color .17s}
#ArchiveList .flat li > a > span{position:relative;float:right;width:16px;height:16px;background-color:$(main.color);color:#fff;font-size:11px;font-weight:400;text-align:center;line-height:16px}
.PopularPosts .post{overflow:hidden;padding:10px 0 0;margin:10px 0 0;border-top:1px dashed #ebebeb}
.PopularPosts .post:first-child{padding:0;margin:0;border:0}
.PopularPosts .post-image-link{position:relative;float:left;width:45px;height:45px;display:block;overflow:hidden;box-sizing:border-box;padding:2px;margin:0 10px 0 0}
.PopularPosts .post-content:hover .post-image-link{background-color:$(main.color)}
.PopularPosts .post-info{overflow:hidden}
.PopularPosts .post-title{font-size:13px;font-weight:400;line-height:1.5em;margin:0}
.PopularPosts .post-title a{display:block;color:$(title.color);transition:color .17s}
.PopularPosts .post-content:hover .post-title .title-text{color:$(title.hover);text-decoration:underline}
.PopularPosts .post-meta{font-size:11px}
.PopularPosts .post-date:before{font-size:10px}
.FeaturedPost .post-image-link{position:relative;float:left;width:45px;height:45px;display:block;overflow:hidden;box-sizing:border-box;padding:2px;margin:0 10px 0 0}
.FeaturedPost .post-content:hover .post-image-link{background-color:$(main.color)}
.FeaturedPost .post-info{overflow:hidden}
.FeaturedPost .post-title{font-size:13px;font-weight:400;line-height:1.5em;margin:0}
.FeaturedPost .post-title a{display:block;color:$(title.color);transition:color .17s}
.FeaturedPost .post-content:hover .post-title .title-text{color:$(title.hover);text-decoration:underline}
.FeaturedPost .post-meta{font-size:11px}
.FeaturedPost .post-date:before{font-size:10px}
.Text{font-size:13px}
.contact-form-widget form{font-weight:400}
.contact-form-name{float:left;width:100%;height:30px;font-family:inherit;font-size:13px;line-height:30px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid #ebebeb}
.contact-form-email{float:left;width:100%;height:30px;font-family:inherit;font-size:13px;line-height:30px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid #ebebeb}
.contact-form-email-message{float:left;width:100%;font-family:inherit;font-size:13px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid #ebebeb}
.contact-form-button-submit{float:left;width:100%;height:30px;background-color:$(main.color);font-size:13px;color:#fff;line-height:30px;cursor:pointer;box-sizing:border-box;padding:0 10px;margin:0;border:0;transition:background .17s ease}
.contact-form-button-submit:hover{background-color:$(main.dark.color)}
.contact-form-error-message-with-border{float:left;width:100%;background-color:#fbe5e5;font-size:11px;text-align:center;line-height:11px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:1px solid #fc6262}
.contact-form-success-message-with-border{float:left;width:100%;background-color:#eaf6ff;font-size:11px;text-align:center;line-height:11px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:1px solid #5ab6f9}
.contact-form-cross{margin:0 0 0 3px}
.contact-form-error-message,.contact-form-success-message{margin:0}
.BlogSearch .search-input{float:left;width:75%;height:30px;background-color:#fff;font-weight:400;font-size:13px;line-height:30px;box-sizing:border-box;padding:5px 10px;border:1px solid #ebebeb;border-right-width:0}
.BlogSearch .search-action{float:right;width:25%;height:30px;font-family:inherit;font-size:13px;line-height:30px;cursor:pointer;box-sizing:border-box;background-color:$(main.color);color:#fff;padding:0 5px;border:0;transition:background .17s ease}
.BlogSearch .search-action:hover{background-color:$(main.dark.color)}
.Profile .profile-img{float:left;width:80px;height:80px;margin:0 15px 0 0;transition:all .17s ease}
.Profile .profile-datablock{margin:0}
.Profile .profile-data .g-profile{display:block;font-size:14px;color:$(title.color);margin:0 0 5px;transition:color .17s ease}
.Profile .profile-data .g-profile:hover{color:$(title.hover)}
.Profile .profile-info > .profile-link{color:$(title.color);font-size:11px;margin:5px 0 0;transition:color .17s ease}
.Profile .profile-info > .profile-link:hover{color:$(title.hover)}
.Profile .profile-datablock .profile-textblock{display:none}
.common-widget .LinkList ul li,.common-widget .PageList ul li{width:calc(50% - 5px);padding:7px 0 0}
.common-widget .LinkList ul li:nth-child(odd),.common-widget .PageList ul li:nth-child(odd){float:left}
.common-widget .LinkList ul li:nth-child(even),.common-widget .PageList ul li:nth-child(even){float:right}
.common-widget .LinkList ul li a,.common-widget .PageList ul li a{display:block;color:$(title.color);font-size:13px;font-weight:400;transition:color .17s ease}
.common-widget .LinkList ul li a:hover,.common-widget .PageList ul li a:hover{color:$(title.hover)}
.common-widget .LinkList ul li:first-child,.common-widget .LinkList ul li:nth-child(2),.common-widget .PageList ul li:first-child,.common-widget .PageList ul li:nth-child(2){padding:0}
#footer-wrapper{background-color:$(main.dark.color)}
#footer-wrapper .container{position:relative;overflow:hidden;margin:0 auto;padding:25px 0}
#menu-footer{float:left;position:relative;display:block}
#menu-footer .widget > .widget-title{display:none}
#menu-footer ul li{float:left;display:inline-block;padding:0;margin:0}
#menu-footer ul li a{font-size:12px;font-weight:400;display:block;color:$(footer.color);padding:0 5px;margin:0 15px 0 0}
#menu-footer ul li:first-child a{padding:0 5px 0 0}
#menu-footer ul li a:hover{text-decoration:underline}
#sub-footer-wrapper{display:block;width:100%;overflow:hidden;color:$(footer.color);padding:0}
#sub-footer-wrapper .container{overflow:hidden;margin:0 auto;padding:10px 0;border-top:2px solid rgba(255,255,255,0.05)}
#social-footer{float:right;position:relative;display:block}
#social-footer .widget > .widget-title{display:none}
#social-footer ul li{float:left;display:inline-block;height:34px;padding:0;margin:0}
#social-footer ul li a{font-size:14px;font-weight:400;display:block;color:$(footer.color);line-height:34px;padding:0 5px;margin:0 0 0 10px;transition:color .17s ease}
#social-footer ul li a:before{color:#f0bd61}
#social-footer ul li:last-child a{padding:0 0 0 5px}
#social-footer ul li a:hover{color:$(title.hover)}
#sub-footer-wrapper .copyright-area{font-size:12px;float:left;height:34px;line-height:34px;font-weight:400}
#sub-footer-wrapper .copyright-area a{color:$(footer.color);transition:color .17s}
#sub-footer-wrapper .copyright-area a:hover{color:$(title.hover)}
.hidden-widgets{display:none;visibility:hidden}
.back-top{display:none;z-index:1010;width:34px;height:34px;position:fixed;bottom:25px;right:25px;cursor:pointer;overflow:hidden;font-size:20px;color:#fff;text-align:center;line-height:34px}
.back-top:before{content:'';position:absolute;top:0;left:0;right:0;bottom:0;background-color:$(main.color);opacity:.5;transition:opacity .17s ease}
.back-top:after{content:'\f106';position:relative;font-family:FontAwesome;font-weight:400;opacity:.8;transition:opacity .17s ease}
.back-top:hover:before,.back-top:hover:after,.nav-active .back-top:after,.nav-active .back-top:before{opacity:1}
.error404 #main-wrapper{width:100%!important;margin:0!important}
.error404 #sidebar-wrapper{display:none}
.errorWrap{color:$(title.color);text-align:center;padding:80px 0 100px}
.errorWrap h3{font-size:160px;line-height:1;margin:0 0 30px}
.errorWrap h4{font-size:25px;margin:0 0 20px}
.errorWrap p{margin:0 0 10px}
.errorWrap a{display:block;color:$(main.color);padding:10px 0 0}
.errorWrap a i{font-size:20px}
.errorWrap a:hover{text-decoration:underline}
@media screen and (max-width: 1100px) {
#outer-wrapper{max-width:100%}
.row{width:100%}
.header-header .container,.header-menu .container,#hot-wrapper{box-sizing:border-box;padding:0 20px}
#header-wrap{height:auto}
.header-logo{max-width:30%}
.header-ads{max-width:70%}
.show-search,.hide-search{right:20px}
#nav-search .search-input{padding:0 46px 0 20px}
#content-wrapper{position:relative;box-sizing:border-box;padding:0 20px;margin:30px 0 0}
#footer-wrapper .container{box-sizing:border-box;padding:25px 20px}
#sub-footer-wrapper .container{box-sizing:border-box;padding:10px 20px}
}
@media screen and (max-width: 980px) {
#content-wrapper > .container{margin:0}
.header-logo{width:100%;max-width:100%;text-align:center;padding:0;margin:0}
#main-menu{display:none}
.slide-menu-toggle,.mobile-nav{display:block}
#header-wrap{padding:0}
.header-header{height:auto;padding:20px 0}
.header-header .container.row{width:100%}
.header-ads{width:100%;max-width:100%;text-align:center;box-sizing:border-box;padding:0}
.header-ads .widget .widget-content{position:relative;padding:20px 0 0;margin:0 auto}
#header-inner a{display:inline-block!important}
.hot-posts{display:flex;flex-wrap:wrap}
.hot-posts .hot-item{display:flex}
#main-wrapper,#sidebar-wrapper{width:100%;padding:0}
}
@media screen and (max-width: 680px) {
#hot-section .show-hot .widget-content,#hot-section .hot-posts{height:auto}
.hot-posts .hot-item{width:100%}
.hot-posts .item-1,.hot-posts .item-2{margin:10px 0 0}
.featured-posts > .col-width{width:100%}
#menu-footer,#sub-footer-wrapper .copyright-area{width:100%;height:auto;line-height:inherit;text-align:center}
#menu-footer{margin:10px 0 0}
#sub-footer-wrapper .copyright-area{margin:10px 0}
#menu-footer ul li{float:none;height:auto}
#menu-footer ul li a{line-height:inherit;margin:0 3px 5px}
#social-footer{width:100%;text-align:center}
#social-footer ul li{float:none;height:auto}
}
@media screen and (max-width: 540px) {
.share-links li a span{display:none}
.share-links li.facebook,.share-links li.twitter,.share-links li.gplus{width:30px}
.inline-ad,.inline-ad > ins{height:auto;min-height:1px;max-height:250px}
.item-post h1.post-title{font-size:25px}
}
@media screen and (max-width: 440px) {
.queryMessage{text-align:center}
.queryMessage a.show-more{width:100%;margin:10px 0 0}
.item-post h1.post-title{font-size:21px}
blockquote{padding:10px 15px}
.about-author{text-align:center}
.about-author .avatar-container{float:none;display:table;margin:0 auto 10px}
#comments ol{padding:0}
.errorWrap{padding:70px 0 100px}
.errorWrap h3{font-size:130px}
}
@media screen and (max-width: 360px) {
.about-author .avatar-container{width:60px;height:60px}
}

/* --- Core Web Vitals Fixes --- */
.header-widget img, .header-logo img {
  width: 478px;
  max-width: 100%;
  height: auto;
  aspect-ratio: 478 / 58;
  display: block;
}
.post-date { color: #555 !important; }


/* --- Core Web Vitals Ultimate Performance & Zero-CLS Fixes --- */

/* @font-face definitions for instant render & zero-latency text display */
@font-face {
  font-family: 'Montserrat';
  font-style: normal;
  font-weight: 400;
  font-display: optional;
  src: url('https://fonts.gstatic.com/s/montserrat/v31/JTUSjIg1_i6t8kCHKm459Wlhyw.woff2') format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'Montserrat';
  font-style: normal;
  font-weight: 700;
  font-display: optional;
  src: url('https://fonts.gstatic.com/s/montserrat/v31/JTUSjIg1_i6t8kCHKm459Wlhyw.woff2') format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: 'FontAwesome';
  src: url('https://stackpath.bootstrapcdn.com/font-awesome/4.7.0/fonts/fontawesome-webfont.woff2?v=4.7.0') format('woff2');
  font-weight: normal;
  font-style: normal;
  font-display: optional;
}

/* Zero-CLS Post Card Stabilization & Font Fallback Lock */
.index-post {
  contain: layout style paint;
}
.index-post .post-image-link {
  width: 45px !important;
  height: 45px !important;
  flex-shrink: 0;
}
.index-post .post-thumb {
  width: 45px !important;
  height: 45px !important;
  aspect-ratio: 1 / 1;
}
.index-post .post-info {
  min-height: 45px;
}
.index-post .post-info .post-title {
  font-size: 13px;
  line-height: 1.45em;
  margin: 0;
}
.index-post .post-info .post-title .title-text {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.45em;
  max-height: 2.9em;
  min-height: 2.9em;
}
.post-date:before, .post-author:before {
  display: inline-block;
  width: 13px;
  height: 13px;
  line-height: 13px;
  text-align: center;
  font-family: FontAwesome;
}
.blog-pager .page-prev, .blog-pager .page-next, .blog-pager .page-num {
  min-width: 32px;
  min-height: 32px;
  line-height: 32px;
  display: inline-block;
  text-align: center;
}

.fa {
  display: inline-block;
  width: 1em;
  height: 1em;
  line-height: 1;
  text-align: center;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}


/* --- Core Govt Portal UI & Monetization Additions --- */
.badge-tag {
  display: inline-block;
  padding: 2px 7px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  border-radius: 3px;
  margin-right: 6px;
  color: #ffffff !important;
  vertical-align: middle;
  letter-spacing: 0.5px;
  line-height: 1.2;
}
.badge-new { background: #b71c1c !important; color: #ffffff !important; font-weight: 700; }
.badge-hot { background: #c0392b !important; color: #ffffff !important; font-weight: 700; }
.badge-update { background: #196f3d !important; color: #ffffff !important; font-weight: 700; }

/* Navigation Responsive Controls: Desktop vs Mobile */
@media screen and (min-width: 981px) {
  #main-menu, #main-menu .widget, #main-menu .show-menu {
    display: block !important;
  }
  .slide-menu-toggle, .mobile-nav {
    display: none !important;
  }
}
@media screen and (max-width: 980px) {
  #main-menu, #main-menu .widget, #main-menu .show-menu {
    display: none !important;
  }
  .slide-menu-toggle {
    display: flex !important;
    align-items: center;
    justify-content: center;
    position: absolute;
    top: 0;
    left: 8px;
    width: 46px;
    height: 46px;
    line-height: 46px;
    font-size: 19px;
    color: #ffffff;
    cursor: pointer;
    z-index: 20;
    padding: 0;
  }
  .mobile-nav {
    display: none !important;
    pointer-events: none !important;
    position: absolute;
    top: 46px;
    left: 0;
    width: 100%;
    height: auto;
    z-index: 9999;
  }
  .nav-active .mobile-nav {
    display: block !important;
    pointer-events: auto !important;
  }
  .mobile-menu {
    position: relative;
    float: none;
    width: 100%;
    background-color: #14243A;
    box-sizing: border-box;
    padding: 10px 14px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    max-height: 80vh;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    visibility: hidden;
    opacity: 0;
    transform-origin: 0 0;
    transform: scaleY(0);
    transition: all 0.22s ease;
  }
  .nav-active .mobile-menu {
    visibility: visible !important;
    opacity: 1 !important;
    transform: scaleY(1) !important;
  }
  .mobile-menu ul {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .mobile-menu ul li {
    width: 100%;
    float: none;
    display: block;
    position: relative;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    line-height: 40px;
    margin: 0;
    padding: 0;
  }
  .mobile-menu ul li:first-child {
    border-top: none;
  }
  .mobile-menu ul li a {
    color: #ffffff;
    font-size: 14px;
    font-weight: 500;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 8px;
    text-decoration: none;
  }
  .mobile-menu ul li a:hover {
    color: #f1c40f;
    background: rgba(255, 255, 255, 0.06);
  }
  .mobile-menu ul li.has-sub .submenu-toggle {
    position: absolute;
    top: 0;
    right: 0;
    width: 44px;
    height: 40px;
    line-height: 40px;
    text-align: center;
    color: #ffffff;
    cursor: pointer;
    z-index: 5;
  }
  .mobile-menu ul li.has-sub .submenu-toggle:after {
    content: '\f107';
    font-family: FontAwesome;
    font-size: 14px;
    display: inline-block;
    transition: transform 0.2s ease;
  }
  .mobile-menu ul li.has-sub.show > .submenu-toggle:after {
    transform: rotate(180deg);
    color: #f1c40f;
  }
  .mobile-menu ul li .m-sub {
    display: none;
    background: rgba(0, 0, 0, 0.25);
    padding: 4px 0 4px 15px;
  }
  .mobile-menu ul li .m-sub li a {
    font-size: 13px;
    opacity: 0.85;
    line-height: 34px;
  }
  .header-menu {
    position: relative;
    height: 46px;
  }
  .header-menu .container {
    position: relative;
    height: 46px;
    padding: 0 50px !important;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }
  .show-search, .hide-search {
    right: 8px !important;
    top: 0 !important;
    width: 46px !important;
    height: 46px !important;
    line-height: 46px !important;
  }
  #nav-search {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 46px;
    z-index: 30;
  }
  #nav-search .search-input {
    width: 100%;
    height: 46px;
    box-sizing: border-box;
    padding: 0 50px 0 16px;
    font-size: 13px;
  }
}

/* Category Label Cloud */
.label-cloud {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 6px !important;
  padding: 10px 0 !important;
}
.label-cloud a {
  display: inline-flex !important;
  align-items: center !important;
  gap: 5px !important;
  background: #ffffff !important;
  border: 1px solid #dcdde1 !important;
  color: #2f3640 !important;
  font-size: 12px !important;
  font-weight: 500 !important;
  padding: 5px 11px !important;
  border-radius: 4px !important;
  transition: all 0.2s ease !important;
  text-decoration: none !important;
}
.label-cloud a:hover {
  background: #17365D !important;
  color: #ffffff !important;
  border-color: #17365D !important;
  box-shadow: 0 2px 8px rgba(171, 24, 61, 0.3) !important;
}
.label-cloud a span {
  font-size: 11px !important;
  color: #718093 !important;
  background: #f1f2f6 !important;
  padding: 1px 6px !important;
  border-radius: 10px !important;
}
.label-cloud a:hover span {
  background: rgba(255, 255, 255, 0.3) !important;
  color: #ffffff !important;
}

/* Header Notification Hub Banner */
.header-notification-box {
  background: rgba(255, 255, 255, 0.12);
  border: 1px dashed rgba(255, 255, 255, 0.45);
  padding: 8px 16px;
  color: #ffffff;
  font-size: 12px;
  border-radius: 4px;
  line-height: 1.4;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: 620px;
}
.header-notification-box i {
  font-size: 22px;
  color: #f1c40f;
}

/* Ads & Monetization Containers (CLS Protected) */
.ad-slot-wrap {
  width: 100%;
  margin: 18px 0;
  text-align: center;
  clear: both;
  overflow: hidden;
  position: relative;
  contain: layout;
}
.ad-label {
  font-size: 10px;
  color: #374151; font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 5px;
  display: block;
}
.resource-promo {
  background: #fafafa;
  border: 1px solid #dfe7f0;
  border-radius: 10px;
  padding: 14px;
  margin: 15px 0;
}
.resource-promo-content {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #fff;
  border: 1px solid #dfe7f0;
  border-radius: 8px;
  padding: 14px 16px;
  text-align: left;
}
.resource-promo-copy {
  flex: 1 1 220px;
  min-width: 0;
}
.resource-promo-copy strong {
  display: block;
  color: #17365d;
  font-size: 14px;
}
.resource-promo-description {
  margin-top: 4px;
  color: #4b5563;
  font-size: 12px;
  line-height: 1.5;
}
.resource-promo-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 36px;
  padding: 8px 13px;
  border-radius: 6px;
  background: #17365d;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
}
.resource-promo-link:hover,
.resource-promo-link:focus-visible {
  background: #102744;
  color: #fff;
}
.ad-slot-sidebar {
  min-height: 250px;
  background: #fafafa;
  border: 1px dashed #e1e4e8;
  border-radius: 4px;
  margin: 20px 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

/* Govt Vacancy Table Styling */
.post-table {
  width: 100%;
  overflow-x: auto;
  margin: 20px 0;
  -webkit-overflow-scrolling: touch;
}
.post-table table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  background: #ffffff;
  border: 1px solid #dcdde1;
}
.post-table th {
  background: #17365D;
  color: #ffffff;
  padding: 10px 12px;
  font-weight: 600;
  text-align: left;
  border: 1px solid #17365D;
}
.post-table td {
  padding: 9px 12px;
  border: 1px solid #e1e4e8;
  color: #333333;
}
.post-table tr:nth-child(even) {
  background: #f8f9fa;
}

/* Recruitment CTA Buttons */
.button.download, .button.demo, .button.apply, .button.official {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  font-size: 13px;
  font-weight: 600;
  border-radius: 4px;
  text-decoration: none !important;
  margin: 6px 6px 6px 0;
  transition: all 0.2s ease;
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}
.button.download {
  background: #e74c3c;
  color: #ffffff !important;
}
.button.download:hover {
  background: #c0392b;
}
.button.apply, .button.demo {
  background: #27ae60;
  color: #ffffff !important;
}
.button.apply:hover, .button.demo:hover {
  background: #219653;
}
.button.official {
  background: #2980b9;
  color: #ffffff !important;
}
.button.official:hover {
  background: #1f6390;
}

/* Telegram Recruitment Alerts Box */
.telegram-join-box {
  background: linear-gradient(135deg, #0088cc, #00a2ff);
  color: #ffffff;
  padding: 14px 18px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 22px 0;
  box-shadow: 0 4px 12px rgba(0, 136, 204, 0.25);
}
.telegram-join-box a {
  background: #ffffff;
  color: #0088cc !important;
  font-weight: 700;
  font-size: 12px;
  padding: 8px 16px;
  border-radius: 4px;
  text-transform: uppercase;
  text-decoration: none !important;
}

/* Social Counters */
.social-color .telegram a { background-color: #0088cc !important; }
.social-color .whatsapp a { background-color: #25d366 !important; }


/* --- Core Web Vitals 100% Zero-CLS & Instant LCP Containment --- */
#content-wrapper {
  contain: layout style;
}
#hot-wrapper, #hot-section {
  contain: layout;
  min-height: 140px;
}
#hot-section .widget {
  display: block !important;
  min-height: 140px;
}
#hot-section .widget > .widget-title {
  display: none;
}
#hot-section .widget-content {
  position: relative;
  overflow: hidden;
  min-height: 140px;
  contain: layout;
}
#hot-section .widget-content {
  color: inherit;
  font-size: inherit;
}

.featured-posts {
  contain: layout style;
  min-height: 140px;
}
.featured-posts > .widget {
  display: block !important;
  position: relative;
  float: left;
  width: 100%;
  margin: 0 0 25px;
  contain: layout style;
  min-height: 140px;
}
/* Featured posts & FeaturedPost widget - Full visibility & clickability */
.featured-posts .widget .widget-content,
.FeaturedPost .widget-content {
  color: inherit !important;
  font-size: inherit !important;
  background: transparent !important;
  border: none !important;
  min-height: 0 !important;
}

/* 100% GPU-composited opacity pulse - Zero CPU/GPU reflows */
@keyframes skel-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

.BlogSearch .widget-content {
  overflow: hidden;
  contain: layout;
  min-height: 32px;
}

@media screen and (max-width: 680px) {
  #hot-section, #hot-wrapper {
    min-height: 95px !important;
    contain: layout;
  }
  #hot-section .show-hot .widget-content, #hot-section .widget-content {
    min-height: 95px !important;
    margin: 15px 0 0 !important;
  }
  #hot-section .widget:not(.show-hot) .widget-content {
    min-height: 95px !important;
  }
  ul.hot-posts {
    display: flex !important;
    flex-wrap: nowrap !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
    scroll-snap-type: x mandatory;
    gap: 8px;
    padding: 0 0 8px 0;
    min-height: 85px !important;
  }
  .hot-posts .hot-item {
    flex: 0 0 78% !important;
    width: 78% !important;
    scroll-snap-align: start;
    margin: 0 !important;
  }
  .hot-posts .hot-item-inner {
    padding: 8px 10px;
    border-radius: 4px;
  }
  .featured-posts, .featured-posts > .widget {
    min-height: 120px !important;
  }
  .featured-posts .widget:not(.show-widget) .widget-content {
    min-height: 120px !important;
  }
}


/* ==========================================================================
   Comprehensive Mobile, Tablet & Cross-Device Responsive Layout Engine
   ========================================================================== */

/* Universal fluid containment */
html, body {
  max-width: 100vw;
  overflow-x: hidden;
  box-sizing: border-box;
  -webkit-text-size-adjust: 100%;
}
*, *:before, *:after {
  box-sizing: inherit;
}
img, video, iframe, embed, object {
  max-width: 100%;
  height: auto;
}
.post-body iframe {
  width: 100% !important;
  aspect-ratio: 16 / 9;
  height: auto !important;
}

/* Tablet & Mobile Breakpoints (<= 980px) */
@media screen and (max-width: 980px) {
  #outer-wrapper {
    width: 100% !important;
    max-width: 100% !important;
    box-shadow: none !important;
  }
  .row {
    width: 100% !important;
    max-width: 100% !important;
  }
  .header-header {
    height: auto !important;
    padding: 16px 12px !important;
  }
  .header-header .container.row {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    gap: 14px !important;
  }
  .header-logo {
    width: 100% !important;
    max-width: 100% !important;
    float: none !important;
    text-align: center !important;
    margin: 0 auto !important;
    padding: 0 !important;
    display: flex !important;
    justify-content: center !important;
  }
  .header-logo .header-image-wrapper {
    display: inline-block !important;
    margin: 0 auto !important;
  }
  .header-widget img, .header-logo img {
    max-width: 280px !important;
    width: 100% !important;
    height: auto !important;
    margin: 0 auto !important;
  }
  .header-ads {
    width: 100% !important;
    max-width: 100% !important;
    float: none !important;
    display: flex !important;
    justify-content: center !important;
    padding: 0 !important;
    margin: 0 !important;
  }
  .header-ads .widget, .header-ads .widget .widget-content {
    width: 100% !important;
    max-width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    line-height: inherit !important;
  }
  .header-notification-box {
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
    margin: 0 auto !important;
    font-size: 11px !important;
    padding: 8px 12px !important;
    gap: 10px !important;
    text-align: left !important;
  }
  .header-notification-box i {
    font-size: 18px !important;
    flex-shrink: 0;
  }
  #content-wrapper {
    padding: 0 12px !important;
    margin: 16px auto 0 !important;
    box-sizing: border-box !important;
    width: 100% !important;
  }
  #content-wrapper > .container {
    margin: 0 !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
  }
  #main-wrapper {
    width: 100% !important;
    max-width: 100% !important;
    float: none !important;
    padding: 0 !important;
    margin: 0 0 25px 0 !important;
    box-sizing: border-box !important;
  }
  #sidebar-wrapper {
    width: 100% !important;
    max-width: 100% !important;
    float: none !important;
    padding: 0 !important;
    margin: 0 !important;
    box-sizing: border-box !important;
  }
  .featured-posts > .col-width {
    width: 100% !important;
    float: none !important;
    margin-bottom: 20px !important;
  }
  .post-table {
    width: 100% !important;
    max-width: 100% !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch !important;
    display: block !important;
    margin: 15px 0 !important;
  }
  .post-table table {
    width: 100% !important;
    min-width: 480px !important;
  }
}

/* Small Tablets & Large Phones (<= 680px) */
@media screen and (max-width: 680px) {
  .header-widget img, .header-logo img {
    max-width: 250px !important;
  }
  .label-cloud {
    gap: 5px !important;
  }
  .label-cloud a {
    padding: 4px 9px !important;
    font-size: 11px !important;
  }
  .item-post h1.post-title {
    font-size: 22px !important;
    line-height: 1.35em !important;
  }
  .item-post .post-body {
    font-size: 14.5px !important;
    line-height: 1.6em !important;
  }
}

/* Phones & Small Screens (<= 540px) */
@media screen and (max-width: 540px) {
  .header-header {
    padding: 12px 8px !important;
  }
  .header-widget img, .header-logo img {
    max-width: 220px !important;
  }
  .header-notification-box {
    font-size: 10.5px !important;
    padding: 6px 10px !important;
    gap: 8px !important;
  }
  .header-notification-box small {
    display: block;
    line-height: 1.3;
  }
  .button.download, .button.demo, .button.apply, .button.official {
    display: flex !important;
    width: 100% !important;
    box-sizing: border-box !important;
    justify-content: center !important;
    margin: 8px 0 !important;
    padding: 11px 14px !important;
    font-size: 13.5px !important;
    text-align: center !important;
  }
  .telegram-join-box {
    flex-direction: column !important;
    text-align: center !important;
    gap: 10px !important;
    padding: 12px !important;
  }
  .telegram-join-box a {
    width: 100% !important;
    box-sizing: border-box !important;
    text-align: center !important;
    display: block !important;
    padding: 9px 12px !important;
  }
  .post-share .share-links {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 6px !important;
  }
  .share-links li {
    flex: 1 1 calc(33.33% - 6px) !important;
    min-width: 80px !important;
  }
  .share-links li a {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    padding: 8px 6px !important;
    font-size: 12px !important;
  }
  .share-links li a span {
    display: inline !important;
  }
  .index-post-wrap {
    padding: 10px !important;
    margin: 0 0 20px !important;
  }
  .index-post .post-info .post-title {
    font-size: 12.5px !important;
  }
  .social-counter.social {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 6px !important;
  }
  .social-counter.social li {
    flex: 1 1 calc(20% - 6px) !important;
    min-width: 44px !important;
    height: 44px !important;
  }
}

/* Very Small Phones (<= 360px) */
@media screen and (max-width: 360px) {
  .header-widget img, .header-logo img {
    max-width: 190px !important;
  }
  .header-notification-box {
    font-size: 10px !important;
    padding: 6px 8px !important;
  }
  .item-post h1.post-title {
    font-size: 19px !important;
  }
}


/* ==========================================================================
   Universal 100% Touch-Friendly Post Hit-Targets & Clickability Fix
   ========================================================================== */

/* Ensure entire card row is relative and touchable */
.index-post, .feat-item, .FeaturedPost .post, .hot-item {
  position: relative !important;
  touch-action: manipulation !important;
  cursor: pointer !important;
  z-index: 2 !important;
}

/* Expand the link hit-target over the entire card area so every tap works */
.index-post .post-title a:after,
.feat-item .post-title a:after,
.FeaturedPost .post-title a:after,
.hot-item .post-title a:after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 5 !important;
}

/* Keep thumbnail images above pseudo-overlay so image clicks also work */
.index-post .post-image-link,
.feat-item .post-image-link,
.FeaturedPost .post-image-link,
.hot-item .post-image-link {
  position: relative !important;
  z-index: 6 !important;
}

/* Ensure post title and links are block-level and easily tappable */
.post-title a {
  display: block !important;
  color: inherit !important;
  -webkit-tap-highlight-color: rgba(171, 24, 61, 0.12);
}
.index-post .post-info, .feat-item .post-info, .FeaturedPost .post-info {
  position: relative !important;
  z-index: 5 !important;
}



/* ============================================================
   TRIPURA GOVT JOBS UPDATES — MODERN PORTAL DESIGN LAYER
   Blogger widgets and post logic remain intact.
   ============================================================ */
:root{--portal-navy:#17365D;--portal-navy-deep:#102744;--portal-ink:#172B45;--portal-muted:#64748b;--portal-line:#e4eaf2;--portal-bg:#f4f7fb;--portal-card:#fff;--portal-saffron:#f4a51c;--portal-green:#16845b;--portal-radius:14px;--portal-shadow:0 8px 28px rgba(19,45,78,.07)}
html{scroll-behavior:smooth}
body{background:var(--portal-bg)!important;color:var(--portal-ink)!important;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important;font-size:15px;line-height:1.65}
#outer-wrapper{max-width:1240px!important;background:#fff!important;box-shadow:0 8px 38px rgba(20,42,70,.06)!important;overflow:hidden}
.row{width:1160px!important;max-width:calc(100% - 40px)!important}
.container{box-sizing:border-box}
a{color:var(--portal-navy)}
a:hover{color:#c27a00}
.portal-topbar{background:#0e2541;color:#dce7f5;font-size:11px;letter-spacing:.075em;font-weight:700}
.portal-topbar .container{height:34px;display:flex;align-items:center;justify-content:space-between}
.portal-topbar b{color:var(--portal-saffron);padding:0 7px}
.portal-topbar-right{color:#bdcde0;letter-spacing:.015em;font-weight:500}
.header-header{height:auto!important;min-height:104px;background:linear-gradient(115deg,#17365d,#102744)!important;padding:16px 0!important;overflow:visible!important}
.header-header .container{display:flex;align-items:center;gap:20px;min-height:72px}
.header-logo{float:none!important;flex:0 0 220px;max-width:220px!important;max-height:none!important;margin:0!important;padding:0!important}
.header-logo img{max-width:210px!important;max-height:70px!important;object-fit:contain}
.brand-copy{display:flex;flex-direction:column;gap:3px;min-width:230px;color:#fff;margin-right:auto}
.brand-copy strong{font-size:22px;line-height:1.2;font-weight:800;letter-spacing:-.035em;color:#fff}
.brand-copy span{font-size:12px;color:#c6d5e7;letter-spacing:.01em}
.header-ads{float:none!important;max-width:420px;flex:0 1 420px;margin-left:auto}
.header-ads .widget .widget-content{width:auto!important;max-height:none!important}
.header-notification-box{display:flex;align-items:center;gap:13px;padding:13px 16px;border:1px solid rgba(255,255,255,.18);border-radius:12px;background:rgba(255,255,255,.08);color:#fff;line-height:1.45}
.header-notification-box .fa{font-size:23px;color:var(--portal-saffron)}
.header-notification-box strong{font-size:12px;letter-spacing:.01em}
.header-notification-box small{font-size:10px;color:#d4e0ee}
.header-menu{height:auto!important;min-height:52px;background:#fff!important;border-bottom:1px solid var(--portal-line);box-shadow:0 4px 14px rgba(15,35,60,.04);z-index:1000}
.header-menu .container{display:flex;align-items:center;min-height:52px;gap:12px}
#main-menu{height:auto!important;flex:1;min-width:0}
#main-menu ul#main-menu-nav{display:flex;align-items:center;flex-wrap:wrap;gap:2px}
#main-menu ul>li{float:none!important}
#main-menu ul>li>a{color:#31445d!important;font-size:12px!important;font-weight:700!important;line-height:52px!important;padding:0 11px!important;border-radius:7px;white-space:nowrap}
#main-menu ul>li:hover>a{color:var(--portal-navy)!important;background:#f0f4f9;text-decoration:none!important}
#main-menu ul>li>ul{top:48px!important;background:#fff!important;border:1px solid var(--portal-line);box-shadow:var(--portal-shadow);border-radius:9px;overflow:hidden}
#main-menu ul>li>ul>li a{color:#31445d!important;padding:8px 14px!important}
#nav-search{margin-left:auto;background:#fff!important;border:1px solid var(--portal-line);border-radius:12px;box-shadow:0 8px 20px rgba(19,45,78,.12)}
#nav-search .search-form{display:flex;align-items:center;gap:10px;height:100%!important;line-height:normal!important;padding:4px 52px 4px 12px!important}
#nav-search .search-input{flex:1 1 auto!important;min-width:0!important;max-width:none!important;width:auto!important;border:1px solid var(--portal-line)!important;border-radius:9px!important;background:#f7f9fc!important;color:var(--portal-ink)!important;height:36px!important;padding:0 14px!important;font-size:14px!important;line-height:normal!important}
#nav-search .search-input:focus{background:#fff!important;border-color:#94a9c2!important;box-shadow:0 0 0 3px rgba(23,54,93,.1)!important}
#nav-search .search-input::placeholder{color:#7b8ba0;opacity:1}
.show-search,.hide-search{display:flex;align-items:center;justify-content:center;right:8px!important;top:6px!important;width:40px!important;height:40px!important;line-height:1!important;border:1px solid var(--portal-line);border-radius:10px;background:#f0f4f9!important;color:var(--portal-navy)!important;text-align:center;transition:background .18s ease,color .18s ease,transform .18s ease}
.show-search:hover,.hide-search:hover{background:#dce9f7!important;color:#102744!important;transform:translateY(-1px)}
#nav-search .hide-search{display:flex!important;align-items:center!important;justify-content:center!important;right:6px!important;top:3px!important;width:40px!important;height:40px!important;line-height:1!important;padding:0!important;border:1px solid var(--portal-line)!important;border-radius:10px!important;background:#f0f4f9!important;color:var(--portal-navy)!important;text-align:center!important}
#nav-search .hide-search:hover{background:#dce9f7!important;color:#102744!important}
.portal-hero{margin:24px auto 18px;width:calc(100% - 40px);max-width:1160px;box-sizing:border-box;border-radius:18px;overflow:hidden;background:radial-gradient(circle at 88% 15%,rgba(244,165,28,.2),transparent 28%),linear-gradient(115deg,#102744 0%,#17365d 60%,#244c76 100%);color:#fff;position:relative}
.portal-hero-inner{padding:36px 42px 30px;max-width:850px}
.portal-eyebrow{display:flex;align-items:center;gap:9px;color:#f8c66f;font-size:10px;font-weight:800;letter-spacing:.14em}
.portal-live-dot{width:7px;height:7px;background:#f4a51c;border-radius:50%;box-shadow:0 0 0 4px rgba(244,165,28,.16)}
.portal-hero h1{font-size:clamp(28px,4vw,42px)!important;line-height:1.13!important;letter-spacing:-.045em;color:#fff!important;margin:14px 0 10px!important;font-weight:850!important}
.portal-hero h1 em{font-style:normal;color:#ffc45b}
.portal-hero p{max-width:690px;color:#d6e2f0;font-size:14px;line-height:1.7;margin:0 0 20px}
.portal-hero-search{display:flex;align-items:center;gap:10px;max-width:690px;padding:6px;background:#fff;border-radius:11px;box-shadow:0 8px 24px rgba(0,0,0,.14)}
.portal-search-symbol{font-size:24px;color:#7c8da3;padding-left:9px;line-height:1}
.portal-hero-search input{appearance:none;flex:1;min-width:0;border:0!important;outline:0!important;background:transparent!important;color:#172b45!important;font-size:13px;padding:10px 2px!important}
.portal-hero-search button{border:0;border-radius:8px;background:var(--portal-saffron);color:#172b45;font-size:12px;font-weight:800;padding:12px 20px;cursor:pointer;white-space:nowrap}
.portal-hero-search button:hover{background:#ffc45b}
.portal-quick-links{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:16px;font-size:11px}
.portal-quick-links span{color:#b9cbe0;font-weight:700}
.portal-quick-links a{color:#fff;border:1px solid rgba(255,255,255,.23);border-radius:30px;padding:4px 10px;font-weight:600;font-size:10px}
.portal-quick-links a:hover{background:rgba(255,255,255,.13);color:#fff}
#hot-wrapper{margin:20px auto 0!important}
#hot-wrapper .widget{background:#fff;border:1px solid var(--portal-line);border-radius:var(--portal-radius);padding:16px 18px;box-shadow:0 4px 18px rgba(19,45,78,.04)}
#hot-wrapper .widget-title,.featured-posts .widget-title,.sidebar .widget-title{font-size:16px!important;font-weight:800!important;color:var(--portal-ink)!important;letter-spacing:-.02em;border-bottom:1px solid var(--portal-line);padding-bottom:12px!important;margin-bottom:14px!important}
#content-wrapper{margin:22px auto 42px!important}
#content-wrapper>.container{display:flex;gap:26px;margin:0!important;align-items:flex-start}
#main-wrapper{float:none!important;width:70%!important;padding:0!important;overflow:visible!important}
#sidebar-wrapper{float:none!important;width:30%!important;padding:0!important}
#main-wrapper .widget{margin-bottom:22px}
.blog-posts .post-outer,.blog-posts .post,.post-outer-container{border:1px solid var(--portal-line)!important;border-radius:13px!important;background:#fff!important;box-shadow:0 4px 18px rgba(19,45,78,.035);overflow:hidden;margin-bottom:16px!important;padding:18px!important;transition:transform .18s ease,box-shadow .18s ease}
.blog-posts .post-outer:hover,.blog-posts .post:hover{transform:translateY(-2px);box-shadow:var(--portal-shadow)}
.post-title,.post-title a{color:var(--portal-ink)!important;font-size:19px!important;line-height:1.4!important;font-weight:800!important;letter-spacing:-.025em}
.post-title a:hover{color:#b87508!important}
.post-body{color:#40536b!important;font-size:15px!important;line-height:1.8!important}
.post-body h2,.post-body h3,.post-body h4{color:var(--portal-ink);line-height:1.35}
.post-body a{color:#155da5;text-decoration:underline;text-underline-offset:2px}
.post-body img{max-width:100%;height:auto;border-radius:8px}
.post-body table{width:100%;border-collapse:collapse;margin:18px 0;font-size:14px}
.post-body th{background:#edf3fa;color:#193a60;font-weight:800}
.post-body th,.post-body td{border:1px solid #dfe7f0;padding:10px 12px;text-align:left}
.post-body tr:nth-child(even){background:#f8fafc}
.post-labels a,.label-size a{display:inline-block;background:#edf3fa!important;color:#24496f!important;border-radius:30px;padding:4px 10px!important;font-size:10px!important;font-weight:700;margin:3px 4px 3px 0}
.post-labels a:hover{background:#dce9f7!important}
.sidebar .widget{background:#fff;border:1px solid var(--portal-line);border-radius:12px;padding:16px;margin-bottom:16px;box-shadow:0 4px 18px rgba(19,45,78,.035)}
.sidebar .widget-content{color:#52647a;font-size:13px;line-height:1.7}
.sidebar .widget-content li{padding:8px 0;border-bottom:1px solid #eef2f6}
.sidebar .widget-content li:last-child{border-bottom:0}
.sidebar .widget-content a{color:#294b70;font-weight:600}
#footer-wrapper{background:#102744!important;color:#d4e0ee!important;margin-top:30px}
#footer-wrapper a{color:#f0bd61}
#footer-wrapper .container{padding-top:26px;padding-bottom:26px}
#footer-wrapper .widget-title{color:#fff}
#footer-wrapper .copyright-area{color:#b8c8da}
.blog-pager a,.blog-pager span{display:inline-block;border:1px solid var(--portal-line);border-radius:8px;padding:8px 13px;background:#fff;color:var(--portal-navy);font-weight:700}
.blog-pager a:hover{background:var(--portal-navy);color:#fff}
#breadcrumb{font-size:11px;color:#8795a7;margin:0 0 14px}
#breadcrumb a{color:#536b86}
.post-timestamp,.post-author,.post-comment-link{font-size:11px;color:#8190a3}
#comments{border:1px solid var(--portal-line);border-radius:12px;padding:18px;margin-top:22px}
input,textarea,select{max-width:100%}
:focus-visible{outline:3px solid rgba(244,165,28,.55);outline-offset:2px}
@media(max-width:1100px){.row{max-width:calc(100% - 32px)!important}.header-ads{max-width:340px}.header-notification-box small{display:none}#main-menu ul>li>a{padding:0 8px!important;font-size:11px!important}}
@media(max-width:900px){.header-header .container{flex-wrap:wrap}.header-ads{display:none}.brand-copy{margin-right:0}.header-menu .container{flex-wrap:wrap}#main-menu ul#main-menu-nav{gap:0}#main-menu ul>li>a{padding:0 8px!important}#content-wrapper>.container{gap:18px}#main-wrapper{width:66%!important}#sidebar-wrapper{width:34%!important}}
@media(max-width:700px){
 .portal-topbar .container{height:auto;min-height:32px;padding-top:7px;padding-bottom:7px}.portal-topbar-right{display:none}
 .header-header{min-height:82px!important;padding:12px 0!important}.header-header .container{gap:12px;min-height:58px}.header-logo{flex-basis:74px;max-width:74px!important}.header-logo img{max-width:72px!important;max-height:56px!important}.brand-copy{min-width:0}.brand-copy strong{font-size:17px}.brand-copy span{font-size:10px}
 .header-menu .container{max-width:100%!important;width:100%!important;padding:0 16px}.header-menu{min-height:48px}.slide-menu-toggle{display:block}.mobile-nav{width:100%}#main-menu ul#main-menu-nav{gap:0}#main-menu ul>li>a{font-size:11px!important;line-height:44px!important;padding:0 8px!important}
 #nav-search .search-input{width:145px!important}.portal-hero{width:calc(100% - 24px);margin:14px auto;border-radius:14px}.portal-hero-inner{padding:26px 20px 22px}.portal-hero h1{font-size:30px!important}.portal-hero p{font-size:12px}.portal-hero-search{gap:4px}.portal-hero-search input{font-size:11px}.portal-hero-search button{padding:11px 13px;font-size:11px}
 .row{max-width:calc(100% - 24px)!important}#content-wrapper{margin:14px auto 28px!important}#content-wrapper>.container{display:block}#main-wrapper,#sidebar-wrapper{float:none!important;width:100%!important}#sidebar-wrapper{margin-top:20px}#main-wrapper{padding:0!important}.post-title,.post-title a{font-size:17px!important}.blog-posts .post-outer,.blog-posts .post,.post-outer-container{padding:14px!important}
}
@media(max-width:420px){.brand-copy strong{font-size:15px}.brand-copy span{max-width:220px}.portal-hero h1{font-size:26px!important}.portal-hero-search{flex-wrap:wrap}.portal-hero-search input{flex:1 1 calc(100% - 45px)}.portal-hero-search button{width:100%}.portal-quick-links{gap:6px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.blog-posts .post-outer,.blog-posts .post{transition:none}}

