b:if.script:
//
var postResults = postPerPage;
var numOfPages = 2;
var pageOf = ["Page", "of"];
var noPage;
var currentPage;
var currentPageNo;
var postLabel;
var locationUrl = location.href;
var home_page = "/";

pageCurrentBlogger();

function startPagination(total) {
  var b = '';
  pageNumber = parseInt(numOfPages / 2);
  if (pageNumber == numOfPages - pageNumber) {
    numOfPages = pageNumber * 2 + 1;
  }
  pageStart = currentPageNo - pageNumber;
  if (pageStart < 1) pageStart = 1;
  lastPageNo = parseInt(total / postResults) + 1;
  if (lastPageNo - 1 == total / postResults) lastPageNo = lastPageNo - 1;
  pageEnd = pageStart + numOfPages - 1;
  if (pageEnd > lastPageNo) pageEnd = lastPageNo;
  b += '<span class="page-of">' + pageOf[0] + ' ' + currentPageNo + ' ' + pageOf[1] + ' ' + lastPageNo + '</span>';
  var prevNum = parseInt(currentPageNo) - 1;
  if (currentPageNo > 1) {
    if (currentPageNo == 2) {
      if (currentPage == 'page') {
        b += '<a class="page-num page-prev" aria-label="Previous Page" title="Previous Page" href="' + home_page + '"></a>';
      } else {
        b += '<a class="page-num page-prev" aria-label="Previous Page" title="Previous Page" href="/search/label/' + postLabel + '?&max-results=' + postResults + '"></a>';
      }
    } else {
      if (currentPage == 'page') {
        b += '<a class="page-num page-prev" aria-label="Previous Page" title="Previous Page" href="#" onclick="getPage(' + prevNum + ');return false"></a>';
      } else {
        b += '<a class="page-num page-prev" aria-label="Previous Page" title="Previous Page" href="#" onclick="getLabelPage(' + prevNum + ');return false"></a>';
      }
    }
  }
  if (pageStart > 1) {
    if (currentPage == 'page') {
      b += '<a class="page-num" aria-label="Page 1" href="' + home_page + '">1</a>';
    } else {
      b += '<a class="page-num" aria-label="Page 1" href="/search/label/' + postLabel + '?&max-results=' + postResults + '">1</a>';
    }
  }
  if (pageStart > 2) {
    b += '<span class="page-num page-dots">...</span>';
  }
  for (var d = pageStart; d <= pageEnd; d++) {
    if (currentPageNo == d) {
      b += '<span class="page-num page-active">' + d + '</span>';
    } else if (d == 1) {
      if (currentPage == 'page') {
        b += '<a class="page-num" aria-label="Page 1" href="' + home_page + '">1</a>';
      } else {
        b += '<a class="page-num" aria-label="Page 1" href="/search/label/' + postLabel + '?&max-results=' + postResults + '">1</a>';
      }
    } else {
      if (currentPage == 'page') {
        b += '<a class="page-num" aria-label="Page ' + d + '" href="#" onclick="getPage(' + d + ');return false">' + d + '</a>';
      } else {
        b += '<a class="page-num" aria-label="Page ' + d + '" href="#" onclick="getLabelPage(' + d + ');return false">' + d + '</a>';
      }
    }
  }
  if (pageEnd < lastPageNo - 1) {
    b += '<span class="page-num page-dots">...</span>';
  }
  if (pageEnd < lastPageNo) {
    if (currentPage == 'page') {
      b += '<a class="page-num" aria-label="Page ' + lastPageNo + '" href="#" onclick="getPage(' + lastPageNo + ');return false">' + lastPageNo + '</a>';
    } else {
      b += '<a class="page-num" aria-label="Page ' + lastPageNo + '" href="#" onclick="getLabelPage(' + lastPageNo + ');return false">' + lastPageNo + '</a>';
    }
  }
  var nextNum = parseInt(currentPageNo) + 1;
  if (currentPageNo < lastPageNo) {
    if (currentPage == 'page') {
      b += '<a class="page-num page-next" aria-label="Next Page" title="Next Page" href="#" onclick="getPage(' + nextNum + ');return false"></a>';
    } else {
      b += '<a class="page-num page-next" aria-label="Next Page" title="Next Page" href="#" onclick="getLabelPage(' + nextNum + ');return false"></a>';
    }
  }
  b += '';
  var pageAreas = document.getElementsByName('pageArea');
  var blogPager = document.getElementById('blog-pager');
  for (var p = 0; p < pageAreas.length; p++) {
    pageAreas[p].innerHTML = b;
  }
  if (pageAreas && pageAreas.length > 0) {
    b = '';
  }
  if (blogPager) {
    blogPager.innerHTML = b;
  }
}

function dataFeed(feedData) {
  var feed = feedData.feed;
  var totalResults = parseInt(feed.openSearch$totalResults.$t, 10);
  startPagination(totalResults);
}

function pageCurrentBlogger() {
  var url = locationUrl;
  if (url.indexOf('/search/label/') != -1) {
    if (url.indexOf('?updated-max') != -1) {
      postLabel = url.substring(url.indexOf('/search/label/') + 14, url.indexOf('?updated-max'));
    } else {
      postLabel = url.substring(url.indexOf('/search/label/') + 14, url.indexOf('?&max'));
    }
  }
  if (url.indexOf('?q=') == -1 && url.indexOf('.html') == -1) {
    if (url.indexOf('/search/label/') == -1) {
      currentPage = 'page';
      if (locationUrl.indexOf('#PageNo=') != -1) {
        currentPageNo = locationUrl.substring(locationUrl.indexOf('#PageNo=') + 8, locationUrl.length);
      } else {
        currentPageNo = 1;
      }
      var s = document.createElement('script');
      s.type = 'text/javascript';
      s.src = home_page + 'feeds/posts/summary?max-results=1&alt=json-in-script&callback=dataFeed';
      document.head.appendChild(s);
    } else {
      currentPage = 'label';
      if (url.indexOf('&max-results=') == -1) {
        postResults = 20;
      }
      if (locationUrl.indexOf('#PageNo=') != -1) {
        currentPageNo = locationUrl.substring(locationUrl.indexOf('#PageNo=') + 8, locationUrl.length);
      } else {
        currentPageNo = 1;
      }
      var s = document.createElement('script');
      s.type = 'text/javascript';
      s.src = home_page + 'feeds/posts/summary/-/' + postLabel + '?alt=json-in-script&callback=dataFeed&max-results=1';
      document.head.appendChild(s);
    }
  }
}

function getPage(pageNum) {
  jsonstart = (pageNum - 1) * postResults;
  noPage = pageNum;
  var head = document.getElementsByTagName('head')[0];
  var script = document.createElement('script');
  script.type = 'text/javascript';
  script.setAttribute('src', home_page + 'feeds/posts/summary?start-index=' + jsonstart + '&max-results=1&alt=json-in-script&callback=findPostDate');
  head.appendChild(script);
}

function getLabelPage(pageNum) {
  jsonstart = (pageNum - 1) * postResults;
  noPage = pageNum;
  var head = document.getElementsByTagName('head')[0];
  var script = document.createElement('script');
  script.type = 'text/javascript';
  script.setAttribute('src', home_page + 'feeds/posts/summary/-/' + postLabel + '?start-index=' + jsonstart + '&max-results=1&alt=json-in-script&callback=findPostDate');
  head.appendChild(script);
}

function findPostDate(feedData) {
  post = feedData.feed.entry[0];
  var pub = post.published.$t.substring(0, 19) + post.published.$t.substring(23, 29);
  var enc = encodeURIComponent(pub);
  if (currentPage == 'page') {
    var dest = '/search?updated-max=' + enc + '&max-results=' + postResults + '#PageNo=' + noPage;
  } else {
    var dest = '/search/label/' + postLabel + '?updated-max=' + enc + '&max-results=' + postResults + '#PageNo=' + noPage;
  }
  location.href = dest;
}
