body.script:
//
$(function(){
  $("a[target='_blank']").each(function(){
    var rel=$(this).attr("rel")||"";
    if(rel.indexOf("noopener")===-1) rel+=" noopener";
    if(rel.indexOf("noreferrer")===-1) rel+=" noreferrer";
    $(this).attr("rel",rel.trim());
  });
});
